&lt;span class="pi"&gt;-&lt;/span&gt; &lt;span class="na"&gt;name&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;Validate React CSP configuration&lt;/span&gt;
&lt;span class="na"&gt;run&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="pi"&gt;|&lt;/span&gt;
&lt;span class="s"&gt;# Check for CSP meta tags in React public/index.html&lt;/span&gt;
&lt;span class="s"&gt;if ! grep -q "Content-Security-Policy" public/index.html; then&lt;/span&gt;
&lt;span class="s"&gt;echo "::error::Missing CSP meta tag in public/index.html"&lt;/span&gt;
&lt;span class="s"&gt;exit 1&lt;/span&gt;
&lt;span class="s"&gt;fi&lt;/span&gt;
&lt;span class="s"&gt;# Check for unsafe-inline in CSP&lt;/span&gt;
&lt;span class="s"&gt;if grep -q "unsafe-inline" public/index.html; then&lt;/span&gt;
&lt;span class="s"&gt;echo "::warning::Unsafe-inline detected in CSP - use nonces instead"&lt;/span&gt;
&lt;span class="s"&gt;fi&lt;/span&gt;

&lt;span class="pi"&gt;-&lt;/span&gt; &lt;span class="na"&gt;name&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;Scan cloud IAM policies for React app roles&lt;/span&gt;
&lt;span class="na"&gt;run&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="pi"&gt;|&lt;/span&gt;
&lt;span class="s"&gt;# Use AWS Config to check IAM roles attached to React app&lt;/span&gt;
&lt;span class="s"&gt;aws configservice select-compliance-details-by-resource \\&lt;/span&gt;
&lt;span class="s"&gt;--resource-type "AWS::IAM::Role" \\&lt;/span&gt;
&lt;span class="s"&gt;--resource-id ${{ secrets.REACT_APP_IAM_ROLE_NAME }} \\&lt;/span&gt;
&lt;span class="s"&gt;&amp;gt; iam-compliance.json&lt;/span&gt;
&lt;span class="s"&gt;# Fail if role is non-compliant&lt;/span&gt;
&lt;span class="s"&gt;if grep -q "NON_COMPLIANT" iam-compliance.json; then&lt;/span&gt;
&lt;span class="s"&gt;echo "::error::React app IAM role is non-compliant with security policies"&lt;/span&gt;
&lt;span class="s"&gt;cat iam-compliance.json&lt;/span&gt;
&lt;span class="s"&gt;exit 1&lt;/span&gt;
&lt;span class="s"&gt;fi&lt;/span&gt;

&lt;span class="pi"&gt;-&lt;/span&gt; &lt;span class="na"&gt;name&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;Check Vercel deployment security (if using Vercel)&lt;/span&gt;
&lt;span class="na"&gt;if&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;${{ secrets.VERCEL_TOKEN != '' }}&lt;/span&gt;
&lt;span class="na"&gt;run&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="pi"&gt;|&lt;/span&gt;
&lt;span class="s"&gt;npm install -g vercel@latest&lt;/span&gt;
&lt;span class="s"&gt;vercel security check \\&lt;/span&gt;
&lt;span class="s"&gt;--token ${{ secrets.VERCEL_TOKEN }} \\&lt;/span&gt;
&lt;span class="s"&gt;--scope ${{ secrets.VERCEL_SCOPE }} \\&lt;/span&gt;
&lt;span class="s"&gt;&amp;gt; vercel-security.json&lt;/span&gt;
&lt;span class="s"&gt;if grep -q "critical" vercel-security.json; then&lt;/span&gt;
&lt;span class="s"&gt;echo "::error::Critical Vercel security issues found"&lt;/span&gt;
&lt;span class="s"&gt;cat vercel-security.json&lt;/span&gt;
&lt;span class="s"&gt;exit 1&lt;/span&gt;
&lt;span class="s"&gt;fi&lt;/span&gt;

&lt;span class="pi"&gt;-&lt;/span&gt; &lt;span class="na"&gt;name&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;Upload scan results to GitHub Security tab&lt;/span&gt;
&lt;span class="na"&gt;uses&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;github/codeql-action/upload-sarif@v3&lt;/span&gt;
&lt;span class="na"&gt;if&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;always()&lt;/span&gt;
&lt;span class="na"&gt;with&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt;
&lt;span class="na"&gt;sarif_file&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;snyk-results.json&lt;/span&gt;
&lt;span class="na"&gt;category&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;snyk-react-scan&lt;/span&gt;

&lt;span class="pi"&gt;-&lt;/span&gt; &lt;span class="na"&gt;name&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;Notify Slack on failure&lt;/span&gt;
&lt;span class="na"&gt;if&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;failure()&lt;/span&gt;
&lt;span class="na"&gt;uses&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;slackapi/slack-github-action@v1.24.0&lt;/span&gt;
&lt;span class="na"&gt;with&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt;
&lt;span class="na"&gt;slack-bot-token&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s"&gt;${{ secrets.SLACK_SECURITY_BOT_TOKEN }}&lt;/span&gt;
&lt;span class="na"&gt;channel-id&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="s"&gt;security-alerts"&lt;/span&gt;
&lt;span class="na"&gt;text&lt;/span&gt;&lt;span class="pi"&gt;:&lt;/span&gt; &lt;span class="s2"&gt;"&lt;/span&gt;&lt;span class="s"&gt;React&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;cloud&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;security&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;scan&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;failed&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;for&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;${{&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;github.repository&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;}}&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;@&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;${{&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;github.sha&lt;/span&gt;&lt;span class="nv"&gt; &lt;/span&gt;&lt;span class="s"&gt;}}"&lt;/span&gt;
&lt;/code&gt;&lt;/pre&gt;

&lt;/div&gt;



&lt;p&gt;Feature&lt;/p&gt;

&lt;p&gt;AWS (Amplify v6.2.1)&lt;/p&gt;

&lt;p&gt;GCP (Firebase v10.5.0)&lt;/p&gt;

&lt;p&gt;Azure (Static Web Apps v2.1.3)&lt;/p&gt;

